from collections import Counter as Cnt
def transform(grid):
    g=[row[:] for row in grid]
    H,W=len(g),len(g[0])
    bg=Cnt(v for row in g for v in row).most_common(1)[0][0]
    zs=[(r,c) for r in range(H) for c in range(W) if g[r][c]==0]
    if zs:  # marker case: rectangle outline + marked rows/cols, drawn in 2
        r0=min(r for r,_ in zs); r1=max(r for r,_ in zs)
        c0=min(c for _,c in zs); c1=max(c for _,c in zs)
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if g[r][c]==0: continue
                if r in (r0,r1) or c in (c0,c1): g[r][c]=2
        for r in range(r0+1,r1):
            if sum(1 for rr,cc in zs if rr==r and c0<cc<c1)>=2:
                for c in range(c0+1,c1):
                    if g[r][c]!=0: g[r][c]=2
        for c in range(c0+1,c1):
            if sum(1 for rr,cc in zs if cc==c and r0<rr<r1)>=2:
                for r in range(r0+1,r1):
                    if g[r][c]!=0: g[r][c]=2
        return g
    # drawn-shape case: fill single-cell gaps between same shape-color runs, in 2
    filled=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg: continue
            for dr,dc in ((0,1),(1,0)):
                pr,pc,qr,qc=r-dr,c-dc,r+dr,c+dc
                if not(0<=pr<H and 0<=pc<W and 0<=qr<H and 0<=qc<W): continue
                v=g[pr][pc]
                if v==g[qr][qc] and v!=bg and v!=0:
                    def runlen(rr,cc):
                        n=0; a,b=rr-dr,cc-dc
                        while 0<=a<H and 0<=b<W and g[a][b]==v: n+=1; a-=dr; b-=dc
                        a,b=rr+dr,cc+dc
                        while 0<=a<H and 0<=b<W and g[a][b]==v: n+=1; a+=dr; b+=dc
                        return n
                    if runlen(pr,pc)>=2 and runlen(qr,qc)>=2:
                        g[r][c]=2; filled.append((r,c,dr,dc,v))
    # extend filled lines through background until a same-color shape cell is reached
    for r,c,dr,dc,v in filled:
        for pr,pc,step in ((r-dr,c-dc,-1),(r+dr,c+dc,1)):
            # find far end of contiguous shape run containing the flank
            a,b=pr,pc
            while True:
                na,nb=a+step*dr,b+step*dc
                if 0<=na<H and 0<=nb<W and g[na][nb]==v: a,b=na,nb
                else: break
            a,b=a+step*dr,b+step*dc
            hit=False
            while 0<=a<H and 0<=b<W:
                if g[a][b]==v: hit=True; break
                if g[a][b]!=bg: break
                a,b=a+step*dr,b+step*dc
            if hit:
                a,b=pr,pc
                while True:
                    na,nb=a+step*dr,b+step*dc
                    if not(0<=na<H and 0<=nb<W) or g[na][nb]==v or g[na][nb]==2: break
                    if g[na][nb]!=bg: break
                    g[na][nb]=2; a,b=na,nb
    return g

