        for r in range(r0+1,r1):
            if sum(1 for rr,cc in zs if rr==r and c0<cc<c1)>=2:
                for c in range(c0+1,c1):
                    if g[r][c]!=0: g[r][c]=2
        for c in range(c0+1,c1):
            if sum(1 for rr,cc in zs if cc==c and r0<rr<r1)>=2:
                for r in range(r0+1,r1):
                    if g[r][c]!=0: g[r][c]=2
        return g
    def runlen(rr,cc,dr,dc,v):  # count same-color neighbors around (rr,cc) along direction
        n=0; a,b=rr-dr,cc-dc
        while 0<=a<H and 0<=b<W and g[a][b]==v: n+=1; a-=dr; b-=dc
        a,b=rr+dr,cc+dc
        while 0<=a<H and 0<=b<W and g[a][b]==v: n+=1; a+=dr; b+=dc
        return n
    filled=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg: continue
            for dr,dc in ((0,1),(1,0)):
                pr,pc,qr,qc=r-dr,c-dc,r+dr,c+dc
                if not(0<=pr<H and 0<=pc<W and 0<=qr<H and 0<=qc<W): continue
                v=g[pr][pc]
                if v==g[qr][qc] and v!=bg and v!=0 and runlen(pr,pc,dr,dc,v)>=1 and runlen(qr,qc,dr,dc,v)>=1:
                    g[r][c]=2; filled.append((r,c,dr,dc,v))
    for r,c,dr,dc,v in filled:
        for side in (-1,1):
            # far end of the same-color run on this side of the gap
            a,b=r+side*dr,c+side*dc
            while True:
                na,nb=a+side*dr,b+side*dc
                if 0<=na<H and 0<=nb<W and g[na][nb]==v: a,b=na,nb
                else: break
            # is there another same-color cell beyond background in this direction?
            x,y=a+side*dr,b+side*dc; hit=False
            while 0<=x<H and 0<=y<W:
                if g[x][y]==v: hit=True; break
                if g[x][y]!=bg: break
                x,y=x+side*dr,y+side*dc
            if hit:  # fill background cells between run end and that cell
                x,y=a+side*dr,b+side*dc
                while 0<=x<H and 0<=y<W and g[x][y]==bg:
                    g[x][y]=2; x,y=x+side*dr,y+side*dc
    return g

